from pathlib import Path
import re
import sys

if len(sys.argv) != 3:
    raise SystemExit('Usage: migrate-v3-learning-experience.py <app.ts> <styles.css>')

app_path = Path(sys.argv[1])
css_path = Path(sys.argv[2])
text = app_path.read_text(encoding='utf-8')

if "const APP_VERSION='3.0.0'" in text:
    print('v3.0.0 already applied')
    raise SystemExit(0)

# Version and data contracts.
text = text.replace("const APP_VERSION='2.2.1'", "const APP_VERSION='3.0.0'")
text = text.replace("schemaVersion:'2.2.1'", "schemaVersion:'3.0.0'")
text = text.replace("state.schemaVersion='2.2.1'", "state.schemaVersion='3.0.0'")
text = text.replace("to:'2.2.1'", "to:'3.0.0'")
text = text.replace("raw.schemaVersion==='2.2.1'", "['2.2.1','3.0.0'].includes(raw.schemaVersion)")

old_activity = "type Activity={id:string,conceptId:string,unitId:string,type:string,prompt:string,options:string[],correct:string[],reason:string,distractorReasons:Record<string,string>,memoryCue:string,examTrap:string,microsoftExample:string,mspExample:string,selectionReason:string,confusionWith?:string};"
new_activity = "type Activity={id:string,conceptId:string,unitId:string,type:string,prompt:string,options:string[],correct:string[],reason:string,distractorReasons:Record<string,string>,memoryCue:string,examTrap:string,microsoftExample:string,mspExample:string,selectionReason:string,confusionWith?:string,qualityStatus?:'draft'|'generated'|'reviewed'|'approved'|'retired',difficulty?:'easy'|'medium'|'hard',objective?:string,commonWrongTemptation?:string,sourceRefs?:string[],contentVersion?:string};"
if old_activity not in text:
    raise SystemExit('Activity contract not found')
text = text.replace(old_activity, new_activity)

old_state = "type State={schemaVersion:string,appVersion:string,learnerId:string,progress:Record<string,Progress>,events:StudyEvent[],notes:{id:string,conceptId:string,text:string,kind:string,createdAt:string}[],lessonPositions:Record<string,number>,completedUnits:string[],xp:number,streak:number,lastStudyDate:string|null,fatigue:number,activeSession?:Session};"
new_state = "type State={schemaVersion:string,appVersion:string,learnerId:string,progress:Record<string,Progress>,events:StudyEvent[],notes:{id:string,conceptId:string,text:string,kind:string,createdAt:string}[],lessonPositions:Record<string,number>,completedUnits:string[],xp:number,coins:number,streak:number,longestStreak:number,lastStudyDate:string|null,fatigue:number,achievements:string[],questionReports:{id:string,questionId:string,conceptId:string,reason:string,details:string,createdAt:string,status:string}[],comparisonPairs:Record<string,{conceptIds:string[],attempts:number,correct:number,lastSeen:string|null}>,cosmetics:{owned:string[],equippedTheme:string,equippedShield:string},lastBackupAt:string|null,activeSession?:Session};"
if old_state not in text:
    raise SystemExit('State contract not found')
text = text.replace(old_state, new_state)

old_vars = "let curriculum:any, units:any, records:any[]=[], concepts:any[]=[], acronyms:any[]=[], assessable:any[]=[], state:State, profile:Profile|null=null, view='home', currentUnit:any=null, feedback:any=null, lessonIndex=0, selected:string[]=[], confidence:Confidence='Fairly sure', attempt=1, guidance='', activityStarted=Date.now(), preAnswerFlag='';"
new_vars = "let curriculum:any, units:any, records:any[]=[], concepts:any[]=[], acronyms:any[]=[], assessable:any[]=[], state:State, profile:Profile|null=null, view='home', currentUnit:any=null, feedback:any=null, lessonIndex=0, selected:string[]=[], confidence:Confidence='Fairly sure', attempt=1, guidance='', activityStarted=Date.now(), preAnswerFlag='', toastMessage='', toastKind='success', aiOpen=false, reportOpen=false, updateAvailable=false;"
if old_vars not in text:
    raise SystemExit('Global state declaration not found')
text = text.replace(old_vars, new_vars)

fresh_pattern = re.compile(r"function fresh\(\):State\{return \{.*?\}\}", re.S)
fresh_new = "function fresh():State{return {schemaVersion:'3.0.0',appVersion:APP_VERSION,learnerId:profile?.id||id(),progress:Object.fromEntries(assessable.map(r=>[r.conceptId,blank(r.conceptId)])),events:[],notes:[],lessonPositions:{},completedUnits:[],xp:0,coins:0,streak:0,longestStreak:0,lastStudyDate:null,fatigue:0,achievements:[],questionReports:[],comparisonPairs:{},cosmetics:{owned:['theme-blue','shield-basic'],equippedTheme:'theme-blue',equippedShield:'shield-basic'},lastBackupAt:null}}"
if not fresh_pattern.search(text):
    raise SystemExit('fresh() not found')
text = fresh_pattern.sub(fresh_new, text, count=1)

insert_after_migrate = """
function ensureV3(s:any):State{
  const b=fresh(), merged={...b,...s};
  merged.progress={...b.progress,...(s?.progress||{})};
  merged.events=Array.isArray(s?.events)?s.events:[];
  merged.notes=Array.isArray(s?.notes)?s.notes:[];
  merged.achievements=Array.isArray(s?.achievements)?s.achievements:[];
  merged.questionReports=Array.isArray(s?.questionReports)?s.questionReports:[];
  merged.comparisonPairs=s?.comparisonPairs||{};
  merged.cosmetics={...b.cosmetics,...(s?.cosmetics||{})};
  merged.coins=Number(s?.coins||0);merged.longestStreak=Number(s?.longestStreak||s?.streak||0);
  merged.lastBackupAt=s?.lastBackupAt||null;merged.schemaVersion='3.0.0';merged.appVersion=APP_VERSION;
  return merged as State;
}
function toast(message:string,kind='success'){toastMessage=message;toastKind=kind;render();setTimeout(()=>{if(toastMessage===message){toastMessage='';render()}},2200)}
function level(){return Math.max(1,Math.floor(state.xp/250)+1)}
const achievementDefs=[
  {id:'first-lesson',name:'First Lesson',coins:25,test:()=>state.events.some(e=>e.type==='concept_introduced')},
  {id:'first-correct',name:'First Correct Answer',coins:20,test:()=>state.events.some(e=>e.type==='activity_answered'&&e.payload.correct===true)},
  {id:'first-understood',name:'First Concept Understood',coins:35,test:()=>Object.values(state.progress).some(p=>['understood','applied','retained','exam-ready'].includes(p.stage))},
  {id:'ten-concepts',name:'10 Concepts Introduced',coins:50,test:()=>Object.values(state.progress).filter(p=>p.stage!=='unseen').length>=10},
  {id:'hundred-questions',name:'100 Questions Answered',coins:100,test:()=>state.events.filter(e=>e.type==='activity_answered').length>=100},
  {id:'seven-day-streak',name:'Seven Day Streak',coins:150,test:()=>state.streak>=7},
  {id:'first-boss',name:'First Boss Battle',coins:75,test:()=>state.events.some(e=>e.type==='session_started'&&e.payload.mode==='boss')},
  {id:'acronym-apprentice',name:'Acronym Apprentice',coins:60,test:()=>acronyms.filter(r=>state.progress[r.conceptId]?.stage!=='unseen').length>=25}
];
function checkAchievements(){for(const a of achievementDefs)if(!state.achievements.includes(a.id)&&a.test()){state.achievements.push(a.id);state.coins+=a.coins;state.events.push(emit('achievement_unlocked',[],{achievementId:a.id,coinReward:a.coins}));toastMessage=`Achievement unlocked: ${a.name} (+${a.coins} coins)`;toastKind='achievement'}}
"""
text = text.replace("function save(){", insert_after_migrate + "\nfunction save(){", 1)
text = text.replace("state=migrate(JSON.parse(stored||'null'));", "state=ensureV3(migrate(JSON.parse(stored||'null')));")
text = text.replace("state=migrate(JSON.parse(String(fr.result)));", "state=ensureV3(migrate(JSON.parse(String(fr.result))));")

# Better fallback question generator. It is explicitly marked generated and is excluded from Exam Mode.
make_pattern = re.compile(r"function makeActivity\(r:any,why:string\):Activity\{.*?\n\}", re.S)
make_new = r'''function makeActivity(r:any,why:string):Activity{
  const u=unitFor(r.conceptId),isA=r.recordClass==='acronym',answer=isA?((r.officialTerms||[])[0]||r.name):r.name;
  const acronym=isA?r.name.split(' - ')[0]:'';
  const siblingPool=concepts.filter(x=>x.conceptId!==r.conceptId&&x.parentId===r.parentId);
  const relatedIds=new Set(r.relatedConcepts||[]);
  const candidates=[...siblingPool,...concepts.filter(x=>relatedIds.has(x.conceptId)),...concepts.filter(x=>x.conceptId!==r.conceptId&&x.objective===r.objective&&x.conceptType===r.conceptType)].filter((x,i,a)=>a.findIndex(y=>y.conceptId===x.conceptId)===i);
  const distractors=(isA?acronyms.filter(x=>x.conceptId!==r.conceptId).map(x=>(x.officialTerms||[])[0]||x.name):candidates.map(x=>x.name)).sort(()=>Math.random()-.5).slice(0,3);
  const options=[answer,...distractors].sort(()=>Math.random()-.5);
  const branch=String(r.objectiveBranch||''),parts=branch.split('>').map((x:string)=>x.trim()).filter(Boolean),context=parts.slice(0,-1).join(' > ')||`objective ${r.objective}`;
  const special:Record<string,string>={
    'Technical':'A security team deploys a firewall rule and endpoint protection policy to reduce exposure. Which control category BEST describes these safeguards?',
    'Managerial':'Senior leadership approves security policies and formal risk-management requirements. Which control category BEST describes these measures?',
    'Operational':'A service desk follows documented account-verification and incident-escalation procedures. Which control category BEST describes these measures?',
    'Physical':'An organisation installs locked doors, bollards, and security cameras around a data centre. Which control category BEST describes these safeguards?',
    'Preventive':'An administrator wants to stop unauthorised software from running before it can affect corporate devices. Which control type BEST meets this objective?',
    'Detective':'A SOC needs a control that identifies suspicious activity after it begins and raises an alert. Which control type BEST meets this objective?',
    'Corrective':'Following a malware incident, the security team restores affected systems to a known-good state. Which control type BEST describes this action?',
    'Deterrent':'Management wants a visible measure that discourages people from attempting unauthorised access. Which control type BEST meets this objective?',
    'Compensating':'A legacy application cannot support the required security control. Which control type provides an alternative safeguard that reduces the same risk?',
    'Directive':'An organisation publishes a policy requiring employees to report suspected security incidents. Which control type BEST describes this requirement?',
    'Role-based access control':'An administrator assigns permissions according to job functions such as Help Desk, Finance, and Security Operations. Which access-control model is being used?',
    'Attribute-based access control':'Access is granted only when user department, device compliance, location, and data sensitivity all meet policy conditions. Which access-control model is being used?',
    'Intrusion detection system':'A network appliance monitors traffic and alerts analysts but does not automatically block packets. Which technology is being used?',
    'Intrusion prevention system':'A security appliance detects malicious network traffic and automatically blocks it inline. Which technology is being used?'
  };
  const prompt=isA?`A technician sees the acronym ${acronym} in a Security+ scenario. What does it stand for?`:special[r.name]||`A security professional is selecting the most precise SY0-701 term for work involving ${context.toLowerCase()}. Which option BEST matches the concept being assessed?`;
  const type=isA?'acronym-in-context':special[r.name]?'scenario-classification':'generated-fallback';
  return {id:id(),conceptId:r.conceptId,unitId:u.unitId,type,prompt,options,correct:[answer],reason:isA?`${acronym} expands to ${answer}. In a scenario, confirm what the acronym is doing rather than relying only on the letters.`:`${answer} is the most precise approved term for this requirement. Focus on its purpose, timing, and scope.`,distractorReasons:Object.fromEntries(options.filter(x=>x!==answer).map(x=>[x,`${x} is related, but it does not match the requirement as precisely as ${answer}.`])),memoryCue:isA?`${acronym} → ${answer}`:`${answer}: match purpose, timing, and scope.`,examTrap:'CompTIA questions often include several related terms. Choose the option that most precisely satisfies the stated requirement.',microsoftExample:`In a Microsoft environment, ${answer} may appear in Microsoft 365, Azure, Entra, Intune, Defender, or Windows configuration and support work.`,mspExample:`In an MSP scenario, ${answer} may be recognised while selecting controls, triaging an incident, reviewing risk, or supporting a customer environment.`,selectionReason:why,confusionWith:candidates[0]?.conceptId,qualityStatus:special[r.name]?'reviewed':'generated',difficulty:special[r.name]?'medium':'easy',objective:String(r.objective||''),commonWrongTemptation:distractors[0]?`${distractors[0]} is tempting because it is related, but its purpose or scope differs.`:'A nearby term may appear plausible.',sourceRefs:['approved-curriculum-v1.2'],contentVersion:'3.0.0'};
}'''
if not make_pattern.search(text):
    raise SystemExit('makeActivity() not found')
text = make_pattern.sub(make_new, text, count=1)

# Adaptive modes and short sessions.
create_pattern = re.compile(r"function createSession\(minutes:number,mode='adaptive'\):Session\{.*?\}\nfunction start", re.S)
create_new = r'''function createSession(minutes:number,mode='adaptive'):Session{
  const now=new Date(),all=mode==='acronym'?acronyms:assessable;
  let pool=all;
  if(mode==='due')pool=all.filter(r=>state.progress[r.conceptId].nextReview&&new Date(state.progress[r.conceptId].nextReview!)<=now);
  if(mode==='mistakes')pool=all.filter(r=>{const p=state.progress[r.conceptId];return p.attempts>p.correct||p.misconceptions.length>0});
  if(mode==='low-confidence')pool=all.filter(r=>state.progress[r.conceptId].guesses>0||state.progress[r.conceptId].confidenceAccuracy<55&&state.progress[r.conceptId].attempts>0);
  if(mode==='comparison')pool=all.filter(r=>state.progress[r.conceptId].misconceptions.length>0);
  if(mode==='exam')pool=all.filter(r=>makeActivity(r,'Exam coverage').qualityStatus==='approved');
  if(!pool.length&&mode==='exam')throw Error('Exam Mode currently requires approved authored questions. Use adaptive or boss mode while the approved bank is expanded.');
  if(!pool.length)pool=all;
  const perMinute=mode==='exam'?1.35:minutes<=1?1:1.1,count=Math.max(1,Math.min(mode==='exam'?90:30,Math.ceil(minutes*perMinute)));
  const ranked=pool.map(r=>({r,p:state.progress[r.conceptId],s:score(r,state.progress[r.conceptId],mode)})).sort((a,b)=>b.s-a.s).slice(0,count);
  const activities=ranked.map(x=>makeActivity(x.r,mode==='mistakes'?'Selected from previous mistakes':mode==='low-confidence'?'Selected from low-confidence evidence':mode==='comparison'?'Selected for confusion-pair practice':mode==='boss'?'Boss battle milestone':x.p.nextReview&&new Date(x.p.nextReview)<=now?'Overdue review':x.p.stage==='unseen'?'Never introduced':x.p.misconceptions.length?'Active misconception':x.p.mastery<55?'Weak mastery':'High-priority reinforcement')).sort(()=>Math.random()-.5);
  return {id:id(),minutes,mode,activities,index:0,startedAt:iso()};
}
function start'''
if not create_pattern.search(text):
    raise SystemExit('createSession() block not found')
text = create_pattern.sub(create_new, text, count=1)

# Home and review navigation.
home_pattern = re.compile(r"function home\(\)\{.*?\}\nfunction learn", re.S)
home_new = r'''function home(){const ps=Object.values(state.progress),studied=ps.filter(p=>p.stage!=='unseen').length,due=ps.filter(p=>p.nextReview&&new Date(p.nextReview)<=new Date()).length,mistakes=ps.filter(p=>p.attempts>p.correct||p.misconceptions.length).length;return shell(`<main class="shell"><section class="hero"><p class="eyebrow">SECURITY+ LEARNING EXPERIENCE</p><h1>Welcome back, ${esc(learnerName())}.</h1><p>Choose a time. The app selects the highest-value activity.</p><div class="heroStats"><span>Level ${level()}</span><span>${state.xp} XP</span><span>${state.coins} coins</span><span>${state.streak} day streak</span></div><button class="primary wide" data-start="5">Continue learning · 5 minutes</button>${mistakes?`<button class="secondary wide" data-mode="mistakes" data-minutes="5">Fix ${mistakes} weak concepts</button>`:''}</section><section><h2>Quick sessions</h2><div class="durationGrid">${[[.5,'30 seconds'],[1,'1 minute'],[2,'2 minutes'],[5,'5 minutes'],[10,'10 minutes'],[15,'15 minutes']].map(([m,l])=>`<button data-start="${m}">◷ <b>${l}</b></button>`).join('')}</div><label>Custom minutes <input id="custom" type="number" min="0.5" max="60" step="0.5" value="7"><button data-action="custom">Start</button></label></section><section class="grid">${[['review','↻','Adaptive review',`${due} due · ${mistakes} weak`],['learn','▤','Learn','101 curriculum units'],['acronyms','Aa','Acronym trainer','336 approved records'],['achievements','★','Achievements',`${state.achievements.length}/${achievementDefs.length} unlocked`],['exam','✓','Exam mode','Approved questions only'],['memory','✎','Memory bank','Notes and useful cues'],['dashboard','▥','Readiness','Domains and weak pairs'],['reports','⚑','Question reports',`${state.questionReports.length} saved`],['settings','⚙','Profile and backup','Import, export, reset']].map(x=>`<button class="tile" data-nav="${x[0]}"><b>${x[1]} ${x[2]}</b><span>${x[3]}</span></button>`).join('')}</section></main>`)}
function learn'''
if not home_pattern.search(text):
    raise SystemExit('home() block not found')
text = home_pattern.sub(home_new, text, count=1)

session_pattern = re.compile(r"function session\(\)\{.*?\}\nfunction finishAnswer", re.S)
session_new = r'''function session(){const s=state.activeSession!,a=s.activities[s.index];if(!a){delete state.activeSession;checkAchievements();save();view='dashboard';return dashboard()}const exam=s.mode==='exam';return shell(`<main class="shell questionScreen"><div class="row"><span>${exam?'Exam':s.mode==='boss'?'Boss battle':'Adaptive session'} · ${s.index+1}/${s.activities.length}</span><span>${exam?'No teaching':'Answer first'}</span></div><div class="progress"><i style="width:${(s.index+1)/s.activities.length*100}%"></i></div>${exam?'':`<section class="selectionReason"><b>Why selected:</b> ${esc(a.selectionReason)}</section>`}<section class="card question"><div class="row"><span class="pill">${esc(a.type)}</span><span class="quality ${a.qualityStatus||'generated'}">${esc(a.qualityStatus||'generated')}</span></div><h1>${esc(a.prompt)}</h1><div class="answers">${a.options.map(o=>`<button data-option="${encodeURIComponent(o)}" class="${selected.includes(o)?'selected':''}">${esc(o)}</button>`).join('')}</div>${exam?'':`<details class="flagPanel"><summary>Need help or want to flag how this feels?</summary><div class="flagActions"><button data-special="dontknow">I don’t know</button><button data-special="teach">Teach me</button><button data-special="forgot">I forgot</button><button data-special="confusing">I’m confusing this</button></div></details><button class="textButton" data-action="report-question">Report question</button>`}</section><button class="primary wide submitAnswer" data-action="submit" ${selected.length?'':'disabled'}>Submit answer</button></main>`)}
function finishAnswer'''
if not session_pattern.search(text):
    raise SystemExit('session() block not found')
text = session_pattern.sub(session_new, text, count=1)

# Commit answer with reinforcement, XP, coins and achievements.
commit_pattern = re.compile(r"function commitAnswer\(rating:Confidence\)\{.*?\}\nfunction feedbackView", re.S)
commit_new = r'''function commitAnswer(rating:Confidence){if(!feedback||feedback.committed)return;confidence=rating;const {a,correct}=feedback,p=state.progress[a.conceptId],guess=rating==='Guessed'||rating==='No idea'||Boolean(feedback.preAnswerFlag),interval=!correct?1:guess?1:feedback.attempts>1?3:7,mastery=Math.max(0,Math.min(100,p.mastery+(correct?(guess?3:12):-8))),order:Stage[]=['unseen','introduced','recognised','understood','applied','retained','exam-ready'];let si=order.indexOf(p.stage);if(correct&&!guess)si=Math.min(order.length-1,Math.max(1,si+1));else if(p.stage==='unseen')si=1;const misconception=!correct?(a.confusionWith||feedback.preAnswerFlag||'precision_vs_related_term'):feedback.preAnswerFlag||'';const np={...p,stage:order[si],mastery,attempts:p.attempts+1,correct:p.correct+(correct?1:0),guesses:p.guesses+(guess?1:0),misconceptions:misconception?[...new Set([...p.misconceptions,misconception])]:p.misconceptions,nextReview:addDays(interval),lastSeen:iso(),recognition:Math.max(p.recognition,correct?mastery:0),understanding:Math.max(p.understanding,correct&&!guess?mastery-8:0),application:Math.max(p.application,correct&&a.type.includes('scenario')?mastery-5:0),scenarioTransfer:Math.max(p.scenarioTransfer,correct&&a.type.includes('scenario')?mastery:0),confidenceAccuracy:Math.round((p.confidenceAccuracy*p.attempts+(correct&&!guess?100:correct?35:rating==='I knew it'?0:50))/(p.attempts+1)),responseTimes:[...p.responseTimes.slice(-19),feedback.responseTimeSeconds]};state.progress[a.conceptId]=np;state.events.push(emit('activity_answered',[a.conceptId],{activityId:a.id,activityType:a.type,qualityStatus:a.qualityStatus,selected:feedback.selected,correct,correctAnswer:a.correct,attempts:feedback.attempts,confidence:rating,preAnswerFlag:feedback.preAnswerFlag||null,responseTimeSeconds:feedback.responseTimeSeconds,nextReview:np.nextReview},a.unitId));const xp=correct?(guess?6:12):4,coins=correct?(guess?2:5):1;state.xp+=xp;state.coins+=coins;if((!correct||guess)&&state.activeSession&&state.activeSession.mode!=='exam'){const repeat=makeActivity(records.find(r=>r.conceptId===a.conceptId),'Reinforcement after an incorrect or low-confidence answer');repeat.options=[...repeat.options].sort(()=>Math.random()-.5);state.activeSession.activities.splice(Math.min(state.activeSession.index+2,state.activeSession.activities.length),0,repeat)}feedback={...feedback,confidence:rating,np,committed:true,xp,coins};checkAchievements();save();render()}
function feedbackView'''
if not commit_pattern.search(text):
    raise SystemExit('commitAnswer() block not found')
text = commit_pattern.sub(commit_new, text, count=1)

feedback_pattern = re.compile(r"function feedbackView\(\)\{.*?\}\nfunction dashboard", re.S)
feedback_new = r'''function feedbackView(){const {a,correct,selected:sel,committed,exam}=feedback;if(!committed)return shell(`<main class="shell feedbackScreen"><section class="card feedback ${exam?'recorded':correct?'correct':'wrong'}"><p class="eyebrow">${exam?'ANSWER RECORDED':correct?'CORRECT':'NOT CORRECT'}</p><h1>${exam?'How did that answer feel?':correct?'Good answer.':'Review this one.'}</h1>${exam?'':`<p><b>Your answer:</b> ${esc(sel.join(', ')||'No response')}</p><p><b>Correct answer:</b> ${esc(a.correct.join(', '))}</p>`}<h2>Did you know it?</h2><div class="postAnswerConfidence">${(['I knew it','Fairly sure','Guessed','No idea'] as Confidence[]).map(c=>`<button data-rating="${c}">${c}</button>`).join('')}</div><p class="muted">Confidence changes mastery and when this concept returns.</p></section></main>`);return shell(`<main class="shell feedbackScreen"><section class="card feedback ${exam?'recorded':correct?'correct':'wrong'}"><p class="eyebrow">${exam?'EXAM RESPONSE SAVED':correct?'CORRECT':'NOT CORRECT'}</p><h1>${correct?'Good answer.':'Review this distinction.'}</h1><p><b>Your answer:</b> ${esc(sel.join(', ')||'No response')}</p><p><b>Correct answer:</b> ${esc(a.correct.join(', '))}</p><p class="shortExplanation">${esc(a.reason)}</p><div class="cue"><b>Memory cue</b><p>${esc(a.memoryCue)}</p></div><p class="reward">+${feedback.xp||0} XP · +${feedback.coins||0} coins</p><details class="explanationPanel"><summary>Why this is correct</summary><p>${esc(a.reason)}</p></details><details class="explanationPanel"><summary>Why my answer was tempting</summary><p>${esc(a.commonWrongTemptation||'The selected option is related, but it does not match the requirement as precisely.')}</p></details><details class="explanationPanel"><summary>Why the other answers are wrong</summary>${Object.entries(a.distractorReasons).map(([k,v])=>`<p><b>${esc(k)}:</b> ${esc(v)}</p>`).join('')}</details><details class="explanationPanel"><summary>Exam tip</summary><p>${esc(a.examTrap)}</p></details><details class="explanationPanel"><summary>Microsoft example</summary><p>${esc(a.microsoftExample)}</p></details><details class="explanationPanel"><summary>MSP example</summary><p>${esc(a.mspExample)}</p></details><details class="explanationPanel"><summary>Ask tutor</summary><button data-action="ask-ai">Open grounded tutor</button></details><div class="feedbackActions"><button data-action="save-cue">Save memory cue</button><button data-action="report-question">Report question</button></div><button class="primary wide" data-action="continue">Continue</button></section></main>`)}
function dashboard'''
if not feedback_pattern.search(text):
    raise SystemExit('feedbackView() block not found')
text = feedback_pattern.sub(feedback_new, text, count=1)

# Add v3 screens and overlays before onboarding.
extra_views = r'''
function reviewView(){const ps=Object.values(state.progress),due=ps.filter(p=>p.nextReview&&new Date(p.nextReview)<=new Date()).length,mistakes=ps.filter(p=>p.attempts>p.correct||p.misconceptions.length).length,low=ps.filter(p=>p.guesses||p.confidenceAccuracy<55&&p.attempts).length;const options=[['adaptive','Continue learning','Mixed high-value session'],['due','Reviews due',`${due} concepts due`],['mistakes','Fix my mistakes',`${mistakes} weak concepts`],['low-confidence','Low confidence',`${low} uncertain concepts`],['acronym','Weak acronyms','Acronym recognition and context'],['comparison','Comparison practice','Recurring confusion pairs'],['boss','Boss battle','Short milestone challenge']];return shell(`<main class="shell"><h1>Adaptive review</h1><p>Choose the type of evidence you want to strengthen.</p>${options.map(([m,n,d])=>`<section class="card reviewCard"><h2>${n}</h2><p>${d}</p><div class="durationGrid">${[[.5,'30s'],[1,'1m'],[2,'2m'],[5,'5m'],[10,'10m']].map(([min,l])=>`<button data-mode="${m}" data-minutes="${min}">${l}</button>`).join('')}</div></section>`).join('')}</main>`)}
function achievementsView(){return shell(`<main class="shell"><h1>Achievements</h1><section class="profileSummary"><div class="shield">${state.cosmetics.equippedShield==='shield-gold'?'◆':'◇'}</div><div><h2>${esc(learnerName())} · Level ${level()}</h2><p>${state.xp} XP · ${state.coins} coins · ${state.streak} day streak</p></div></section>${achievementDefs.map(a=>{const unlocked=state.achievements.includes(a.id);return `<section class="card achievement ${unlocked?'unlocked':'locked'}"><div class="row"><h2>${unlocked?'★':'○'} ${a.name}</h2><span>${a.coins} coins</span></div><p>${unlocked?'Unlocked from real study evidence.':'Locked — keep studying to make progress.'}</p></section>`}).join('')}<section class="card"><h2>Cosmetics</h2>${[['theme-blue','Blue theme',0],['theme-purple','Purple theme',150],['theme-oled','OLED black',250],['shield-gold','Gold shield',400]].map(([idn,name,cost])=>{const owned=state.cosmetics.owned.includes(String(idn));return `<div class="cosmetic"><b>${name}</b><span>${owned?'Owned':cost+' coins'}</span><button data-cosmetic="${idn}" data-cost="${cost}">${owned?'Equip':'Unlock'}</button></div>`}).join('')}</section></main>`)}
function reportsView(){return shell(`<main class="shell"><h1>Question reports</h1><p>Reports stay on this device and are included in backups.</p><button data-action="export-reports">Export reports</button>${state.questionReports.slice().reverse().map(r=>`<section class="card"><div class="row"><span class="pill">${esc(r.reason)}</span><span>${new Date(r.createdAt).toLocaleDateString()}</span></div><p><b>${esc(records.find(x=>x.conceptId===r.conceptId)?.name||r.conceptId)}</b></p><p>${esc(r.details||'No additional details.')}</p></section>`).join('')||'<section class="card"><p>No reports saved.</p></section>'}</main>`)}
function aiPanel(){if(!aiOpen)return '';const a=feedback?.a||state.activeSession?.activities[state.activeSession.index]||null,r=a?records.find(x=>x.conceptId===a.conceptId):currentUnit?records.find(x=>x.conceptId===currentUnit.conceptIds[lessonIndex]):null;return `<div class="sheetBackdrop" data-action="close-ai"><section class="bottomSheet" role="dialog" aria-modal="true" aria-label="Grounded tutor"><div class="sheetHandle"></div><div class="row"><h2>Grounded tutor</h2><button data-action="close-ai">Close</button></div><p class="notice">Offline deterministic tutor. It uses the approved curriculum context and cannot provide open-ended remote AI answers.</p><h3>${esc(r?.name||a?.correct?.[0]||'Current concept')}</h3><div class="quickPrompts">${['Explain more simply','Explain like I’m new','Use an analogy','Microsoft example','MSP example','Compare concepts','Why was my answer wrong?','Give me an exam tip','Test me again'].map(q=>`<button data-tutor="${q}">${q}</button>`).join('')}</div><div id="tutor-output" class="tutorOutput"><b>Current explanation</b><p>${esc(a?.reason||`Focus on the purpose, timing, and scope of ${r?.name||'the current concept'}.`)}</p><p><b>Memory cue:</b> ${esc(a?.memoryCue||r?.objectiveBranch||'Use the most precise official term.')}</p></div></section></div>`}
function reportPanel(){if(!reportOpen)return '';const a=feedback?.a||state.activeSession?.activities[state.activeSession.index];return `<div class="sheetBackdrop"><section class="bottomSheet" role="dialog" aria-modal="true"><div class="row"><h2>Report question</h2><button data-action="close-report">Close</button></div><p>${esc(a?.prompt||'Current question')}</p><label>Reason <select id="report-reason">${['poor wording','unrealistic scenario','wrong explanation','wrong answer','multiple possible answers','typo','too easy','too hard','outside exam scope','other'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Details <textarea id="report-details" placeholder="What should be improved?"></textarea></label><button class="primary wide" data-action="save-report">Save report</button></section></div>`}
function toastView(){return toastMessage?`<div class="toast ${toastKind}" role="status" aria-live="polite"><b>${toastKind==='achievement'?'★':'✓'}</b><span>${esc(toastMessage)}</span></div>`:''}
'''
text = text.replace("function onboarding(){", extra_views + "\nfunction onboarding(){", 1)

render_pattern = re.compile(r"function render\(\)\{.*?\}\napp\.addEventListener", re.S)
render_new = "function render(){app.innerHTML=(view==='onboarding'?onboarding():view==='home'?home():view==='learn'?learn():view==='lesson'?lesson():view==='session'?session():view==='feedback'?feedbackView():view==='dashboard'?dashboard():view==='acronyms'?acronymsView():view==='exam'?examView():view==='memory'?memoryView():view==='review'?reviewView():view==='achievements'?achievementsView():view==='reports'?reportsView():settingsView())+aiPanel()+reportPanel()+toastView();document.documentElement.dataset.theme=state?.cosmetics?.equippedTheme||'theme-blue';if(view==='session'||view==='feedback')document.querySelector('nav')?.remove()}\napp.addEventListener"
if not render_pattern.search(text):
    raise SystemExit('render() block not found')
text = render_pattern.sub(render_new, text, count=1)

# Replace click/change handlers with v3-aware interactions.
handler_pattern = re.compile(r"app\.addEventListener\('click'.*?\);\napp\.addEventListener\('change'.*?\);", re.S)
handler_new = r'''app.addEventListener('click',e=>{const t=(e.target as HTMLElement).closest<HTMLElement>('button');if(!t)return;if(t.dataset.nav){navigate(t.dataset.nav);return}if(t.dataset.start){start(Number(t.dataset.start));return}if(t.dataset.startAcr){start(Number(t.dataset.startAcr),'acronym');return}if(t.dataset.mode){start(Number(t.dataset.minutes||5),t.dataset.mode);return}if(t.dataset.unit){currentUnit=units.learningUnits.find((u:any)=>u.unitId===t.dataset.unit);lessonIndex=state.lessonPositions[currentUnit.unitId]||0;view='lesson';render();return}if(t.dataset.option){selected=[decodeURIComponent(t.dataset.option)];render();return}if(t.dataset.rating){commitAnswer(t.dataset.rating as Confidence);return}if(t.dataset.special){preAnswerFlag=t.dataset.special;const ac=state.activeSession!.activities[state.activeSession!.index];state.events.push(emit('learning_branch_selected',[ac.conceptId],{branch:preAnswerFlag},ac.unitId));if(preAnswerFlag==='dontknow'||preAnswerFlag==='teach'||preAnswerFlag==='forgot'||preAnswerFlag==='confusing')aiOpen=true;save();render();return}if(t.dataset.tutor){const out=document.querySelector('#tutor-output');const a=feedback?.a||state.activeSession?.activities[state.activeSession.index],q=t.dataset.tutor;let msg=a?.reason||'Use the approved curriculum definition and distinguish purpose, timing, and scope.';if(q?.includes('Microsoft'))msg=a?.microsoftExample;if(q?.includes('MSP'))msg=a?.mspExample;if(q?.includes('exam tip'))msg=a?.examTrap;if(q?.includes('analogy'))msg=`Think of ${a?.correct?.[0]||'this concept'} as a tool selected for one precise job. A related tool may look similar but solves a different problem.`;if(q==='Test me again'){aiOpen=false;if(state.activeSession&&a)state.activeSession.activities.splice(state.activeSession.index,0,makeActivity(records.find(r=>r.conceptId===a.conceptId),'Tutor-requested retest'));save();view='session';resetActivity();render();return}if(out)out.innerHTML=`<b>${esc(q)}</b><p>${esc(msg)}</p>`;state.events.push(emit('tutor_prompt_used',a?[a.conceptId]:[],{prompt:q}));save();return}if(t.dataset.cosmetic){const item=t.dataset.cosmetic!,cost=Number(t.dataset.cost||0),owned=state.cosmetics.owned.includes(item);if(!owned){if(state.coins<cost){toast('Not enough coins','error');return}state.coins-=cost;state.cosmetics.owned.push(item);state.events.push(emit('cosmetic_unlocked',[],{item,cost}))}if(item.startsWith('theme-'))state.cosmetics.equippedTheme=item;else state.cosmetics.equippedShield=item;state.events.push(emit('cosmetic_equipped',[],{item}));save();toast('Cosmetic equipped');return}const a=t.dataset.action;if(a==='complete-onboarding'){const name=(document.querySelector('#onboard-name') as HTMLInputElement)?.value.trim();if(!name){toast('Enter a display name','error');return}profile={id:state?.learnerId||id(),name,examDate:(document.querySelector('#onboard-exam') as HTMLInputElement)?.value||null,createdAt:iso()};state.learnerId=profile.id;saveProfile();state.events.push(emit('profile_created',[],{hasExamDate:Boolean(profile.examDate)}));save();view='home';toast('Profile saved');return}if(a==='save-profile-settings'){const name=(document.querySelector('#profile-name') as HTMLInputElement)?.value.trim();if(!name){toast('Display name cannot be blank','error');return}profile={...(profile||{id:state.learnerId,createdAt:iso()}),name,examDate:(document.querySelector('#profile-exam') as HTMLInputElement)?.value||null};state.learnerId=profile.id;saveProfile();state.events.push(emit('profile_updated',[],{hasExamDate:Boolean(profile.examDate)}));save();toast('Profile saved');return}if(a==='review'){view='review';render();return}if(a==='custom'){start(Number((document.querySelector('#custom') as HTMLInputElement).value));return}if(a==='lesson-prev'){lessonIndex=Math.max(0,lessonIndex-1);render();return}if(a==='lesson-next'){const ids=currentUnit.conceptIds,r=ids[lessonIndex],p=state.progress[r];p.stage=p.stage==='unseen'?'introduced':p.stage;p.lastSeen=iso();p.nextReview=p.nextReview||addDays(1);state.events.push(emit('concept_introduced',[r],{},currentUnit.unitId));state.lessonPositions[currentUnit.unitId]=Math.min(ids.length-1,lessonIndex+1);if(lessonIndex+1<ids.length)lessonIndex++;else{state.completedUnits=[...new Set([...state.completedUnits,currentUnit.unitId])];view='learn'}checkAchievements();save();render();return}if(['explain','ms-example','msp-example','ask-ai'].includes(a||'')){aiOpen=true;render();return}if(a==='close-ai'){aiOpen=false;render();return}if(a==='report-question'){reportOpen=true;render();return}if(a==='close-report'){reportOpen=false;render();return}if(a==='save-report'){const q=feedback?.a||state.activeSession?.activities[state.activeSession.index],reason=(document.querySelector('#report-reason') as HTMLSelectElement)?.value||'other',details=(document.querySelector('#report-details') as HTMLTextAreaElement)?.value.trim()||'';if(q){state.questionReports.push({id:id(),questionId:q.id,conceptId:q.conceptId,reason,details,createdAt:iso(),status:'open'});state.events.push(emit('question_reported',[q.conceptId],{questionId:q.id,reason},q.unitId));save()}reportOpen=false;toast('Question report saved');return}if(a==='submit'){const s=state.activeSession!,ac=s.activities[s.index],correct=ac.correct.length===selected.length&&ac.correct.every(x=>selected.includes(x));finishAnswer(correct);return}if(a==='continue'){resetActivity();view=state.activeSession&&state.activeSession.index<state.activeSession.activities.length?'session':'dashboard';render();return}if(a==='save-cue'){state.notes.push({id:id(),conceptId:feedback.a.conceptId,text:feedback.a.memoryCue,kind:'memory cue',createdAt:iso()});state.events.push(emit('memory_saved',[feedback.a.conceptId],{text:feedback.a.memoryCue}));save();toast('Memory cue saved');return}if(a==='save-note'){const el=document.querySelector<HTMLTextAreaElement>('#note')!;if(el.value.trim()){state.notes.push({id:id(),conceptId:'GENERAL',text:el.value.trim(),kind:'own note',createdAt:iso()});state.events.push(emit('note_saved',[],{}));save();toast('Note saved')}return}if(a==='start-exam'){try{start(Number((document.querySelector('#exam-min') as HTMLInputElement).value),'exam')}catch(err){toast(String(err),'error')}return}if(a==='export'){const payload={profile,state,exportedAt:iso(),schemaVersion:'3.0.0'};const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));link.download=`security-plus-${learnerName().toLowerCase().replace(/[^a-z0-9]+/g,'-')||'learner'}-${new Date().toISOString().slice(0,10)}.json`;link.click();state.lastBackupAt=iso();state.events.push(emit('backup_exported',[],{}));save();toast('Progress exported successfully');return}if(a==='export-reports'){const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([JSON.stringify({reports:state.questionReports,exportedAt:iso()},null,2)],{type:'application/json'}));link.download='security-plus-question-reports.json';link.click();toast('Question reports exported');return}if(a==='reset'&&confirm('Reset all local progress? Export first if needed.')){state=fresh();save();toast('Progress reset');return}if(a==='update-now'){location.reload();return}});
app.addEventListener('change',e=>{const t=e.target as HTMLInputElement;if(t.id==='import'&&t.files?.[0]){const f=t.files[0],fr=new FileReader();fr.onload=()=>{try{const parsed=JSON.parse(String(fr.result)),candidate=parsed.state||parsed;if(!candidate.schemaVersion)throw Error('Missing schema version');if(confirm(`Import schema ${candidate.schemaVersion}? Compatible records will be preserved.`)){state=ensureV3(migrate(candidate));if(parsed.profile){profile=parsed.profile;saveProfile()}state.events.push(emit('backup_imported',[],{file:f.name,fromSchema:candidate.schemaVersion}));save();toast('Progress imported successfully')}}catch(err){toast(`Import failed: ${String(err)}`,'error')}};fr.readAsText(f)}});'''
if not handler_pattern.search(text):
    raise SystemExit('Event handlers not found')
text = handler_pattern.sub(handler_new, text, count=1)

# Service worker registration with update signal.
text = text.replace("if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(console.error))", "if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').then(reg=>{reg.addEventListener('updatefound',()=>{const w=reg.installing;if(w)w.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller){updateAvailable=true;toast('Update available')}})});navigator.serviceWorker.addEventListener('controllerchange',()=>{toastMessage='Updated successfully';toastKind='success';render()})}).catch(console.error))")

app_path.write_text(text, encoding='utf-8')

css = css_path.read_text(encoding='utf-8')
css += r'''
:root[data-theme="theme-purple"]{--accent:#b98cff;--accent2:#6e4bb3}
:root[data-theme="theme-oled"] body{background:#000}
.heroStats{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.heroStats span{background:#0d1725;border:1px solid #2b3b52;border-radius:999px;padding:7px 10px;font-size:.88rem}
.secondary{background:#162337;border:1px solid #4a617e;color:#fff}.textButton{background:transparent;border:0;color:#9fc9f2;text-decoration:underline;margin-top:10px}
.quality{font-size:.72rem;text-transform:uppercase;letter-spacing:.06em;border:1px solid #3b4b62;border-radius:999px;padding:4px 8px}.quality.generated{color:#ffd58a}.quality.reviewed,.quality.approved{color:#8ee6b4}
.shortExplanation{font-size:1.05rem;line-height:1.55}.reward{font-weight:800;color:#ffd978}.feedbackActions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:14px 0}
.toast{position:fixed;z-index:1000;left:50%;bottom:calc(22px + env(safe-area-inset-bottom));transform:translateX(-50%);width:min(92vw,520px);display:flex;gap:10px;align-items:center;background:#123522;border:1px solid #3cb875;color:#eafff2;border-radius:14px;padding:14px 16px;box-shadow:0 16px 40px #0009}.toast.error{background:#421c22;border-color:#df6470}.toast.achievement{background:#3b2d0d;border-color:#d8a92d;color:#fff3c4}
.sheetBackdrop{position:fixed;z-index:900;inset:0;background:#000a;display:flex;align-items:flex-end;justify-content:center}.bottomSheet{width:min(100%,720px);max-height:88dvh;overflow:auto;background:#101a29;border:1px solid #33445d;border-radius:24px 24px 0 0;padding:12px 18px calc(24px + env(safe-area-inset-bottom));box-shadow:0 -20px 60px #000b}.sheetHandle{width:44px;height:5px;border-radius:999px;background:#52627a;margin:0 auto 14px}.quickPrompts{display:grid;grid-template-columns:1fr 1fr;gap:8px}.tutorOutput{background:#0a1320;border:1px solid #2d3b50;border-radius:14px;padding:14px;margin-top:14px}
.reviewCard .durationGrid{grid-template-columns:repeat(5,minmax(0,1fr))}.profileSummary{display:flex;gap:14px;align-items:center;background:#121e30;border:1px solid #2e4059;border-radius:18px;padding:16px;margin-bottom:14px}.shield{font-size:3rem}.achievement.unlocked{border-color:#c7a741}.achievement.locked{opacity:.72}.cosmetic{display:grid;grid-template-columns:1fr auto auto;gap:10px;align-items:center;padding:10px 0;border-bottom:1px solid #26364b}
@media(max-width:520px){.reviewCard .durationGrid{grid-template-columns:repeat(3,1fr)}.quickPrompts{grid-template-columns:1fr}.feedbackActions{grid-template-columns:1fr}.cosmetic{grid-template-columns:1fr auto}.cosmetic button{grid-column:1/-1}}
'''
css_path.write_text(css, encoding='utf-8')
print('v3.0.0 learning experience migration applied')
